"""Stable task binding checks. No credentials or response data in errors."""
import os
import time
from pathlib import Path
from contextlib import contextmanager, nullcontext
from .stable_response import decode_response


def active_brand(record):
    record = decode_response(record)
    if not isinstance(record, dict):
        return None
    if record.get('success') is False or record.get('succeed') is False:
        return None
    for key in ('orgId', 'brandId', 'currentOrgId', 'currentBrandId'):
        if record.get(key) is not None:
            return str(record[key])
    for key in ('data', 'result', 'organization', 'org', 'brand', 'loginRecord'):
        found = active_brand(record.get(key))
        if found:
            return found
    return None


@contextmanager
def session_lock():
    directory = os.environ.get('WENDING_SHARED_AUTH_DIR')
    if not directory:
        yield
        return
    directory = os.environ.get('WENDING_SESSION_LOCK_DIR') or directory
    Path(directory).mkdir(parents=True, exist_ok=True)
    with open(Path(directory) / 'session.lock', 'a+b') as lock:
        if os.fstat(lock.fileno()).st_size == 0:
            lock.write(b'0'); lock.flush()
        deadline = time.monotonic() + 20
        while True:
            lock.seek(0)
            try:
                if os.name == 'nt':
                    import msvcrt
                    msvcrt.locking(lock.fileno(), msvcrt.LK_NBLCK, 1)
                else:
                    import fcntl
                    fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except OSError:
                if time.monotonic() >= deadline:
                    raise RuntimeError('其他对话正在使用问鼎会话，请稍后重试；无需重新登录。') from None
                time.sleep(0.05)
        try: yield
        finally:
            lock.seek(0)
            if os.name == 'nt': msvcrt.locking(lock.fileno(), msvcrt.LK_UNLCK, 1)
            else: fcntl.flock(lock, fcntl.LOCK_UN)


def request_lock(client):
    if getattr(client, '_stable_login_worker', False) or getattr(client, '_stable_checking_scope', False):
        return nullcontext()
    return session_lock()


def verify(client, restore=False):
    from . import config
    from .api import CrmAPI
    cfg = config.load_config()
    expected = str(cfg.get('stable_brand_id') or '')
    if not expected or not cfg.get('wnToken'):
        raise RuntimeError('此任务尚未绑定问鼎账号和品牌，请打开任务顶部的问鼎 CLI 登录。')
    if client.wnToken != cfg.get('wnToken'):
        raise RuntimeError('任务登录态已变化，本次查询已停止，请重新运行。')
    if str(cfg.get('stable_brand_channel', cfg.get('third_login_channel', '0'))) != str(cfg.get('third_login_channel', '0')):
        raise RuntimeError('登录渠道已更换，请为此对话重新选择品牌，无需重复验证手机号。')
    probe = CrmAPI(wnToken=client.wnToken)
    probe._stable_checking_scope = True
    record = probe.third_login_login_record(channel=str(cfg.get('third_login_channel', '0')))
    if active_brand(record) != expected and restore and os.environ.get('WENDING_SHARED_AUTH_DIR'):
        switched = decode_response(probe.third_login_switch_brand(channel=str(cfg.get('third_login_channel', '0')), brandId=expected))
        if switched is False or (isinstance(switched, dict) and (switched.get('success') is False or switched.get('succeed') is False)):
            raise RuntimeError('无法恢复此对话的品牌，请在问鼎 CLI 表单重新选择品牌。')
        record = probe.third_login_login_record(channel=str(cfg.get('third_login_channel', '0')))
    if active_brand(record) != expected:
        raise RuntimeError('当前服务端品牌与此任务绑定的品牌不一致，已停止返回数据。请在本任务的问鼎 CLI 表单重新选择品牌。')


def before_request(client, headers, use_gateway):
    if not os.environ.get('WENDING_CONFIG_DIR') or getattr(client, '_stable_login_worker', False) or getattr(client, '_stable_checking_scope', False):
        return False
    if not use_gateway or headers.get('methodName') == 'switchOrganization':
        raise RuntimeError('任务内不允许通过命令改变登录或品牌，请使用任务顶部的问鼎 CLI 表单。')
    verify(client, restore=True)
    return True
